<section class="owner-section-page owner-page visits-page"><div class="page-heading"><span class="eyebrow">مراقبة الاستخدام</span><h1>سجل الزيارات</h1><p>يعرض آخر الزيارات للموقع مع عنوان IP والمسار وحالة تسجيل الدخول والحساب المرتبط عند توفره. البيانات للاستخدام الإداري فقط. لا يتم احتساب زيارات مالك الموقع أو عرضها ضمن هذا السجل.</p></div><?php require __DIR__.'/owner_nav.php'; ?><div class="visit-stats"><article class="dashboard-card"><span class="card-label">إجمالي آخر 30 يومًا</span><strong><?= (int)($visitStats['total']??0) ?></strong><small>زيارة مسجلة</small></article><article class="dashboard-card"><span class="card-label">عناوين IP مختلفة</span><strong><?= (int)($visitStats['unique_ips']??0) ?></strong><small>ضمن آخر 30 يومًا</small></article><article class="dashboard-card"><span class="card-label">حسابات مسجلة</span><strong><?= (int)($visitStats['signed_in']??0) ?></strong><small>طلبات أثناء تسجيل الدخول</small></article><article class="dashboard-card"><span class="card-label">زوار</span><strong><?= (int)($visitStats['guests']??0) ?></strong><small>بدون حساب مسجل</small></article></div><section class="dashboard-card visits-table-card"><div class="section-card-heading"><div><span class="card-label">آخر 250 زيارة</span><h2>التفاصيل</h2></div><span class="owner-badge">IP مباشر</span></div><div class="owner-table-wrap"><table class="owner-table visits-table"><thead><tr><th>الوقت</th><th>IP</th><th>الحساب</th><th>الحالة</th><th>المسار</th><th>المتصفح</th></tr></thead><tbody><?php foreach(($visits??[]) as $visit): ?><tr><td><?= e(saudi_datetime($visit['created_at'])) ?></td><td><code class="visit-ip"><?= e($visit['visitor_ip']) ?></code></td><td><?php if (!empty($visit['full_name'])): ?><strong><?= e($visit['full_name']) ?></strong><small><?= e($visit['email']) ?></small><?php else: ?><span class="muted-value">زائر بدون حساب</span><?php endif; ?></td><td><span class="visit-auth <?= (int)$visit['is_authenticated']?'is-auth':'is-guest' ?>"><?= (int)$visit['is_authenticated']?'مسجل الدخول':'زائر' ?></span></td><td><code class="visit-route"><?= e($visit['route']) ?></code></td><td><span class="visit-agent"><?= e($visit['user_agent']?:'غير متاح') ?></span></td></tr><?php endforeach; if(empty($visits)): ?><tr><td colspan="6"><div class="empty-state">لا توجد زيارات مسجلة بعد.</div></td></tr><?php endif; ?></tbody></table></div></section></section>